from fastapi import APIRouter, HTTPException, Depends
from models.data_source import DataSource
from utils.airflow_trigger import trigger_dag
from security.oauth2 import get_current_user
import uuid

router = APIRouter(prefix='/api/data-sources', tags=['Data Sources'])

@router.post('/register')
def register_source(source: DataSource, user=Depends(get_current_user)):
    try:
        profiling_job_id = str(uuid.uuid4())
        trigger_dag('profiling_dag', conf={'source': source.source_name, 'connection': source.connection_params})
        metrics = {'completeness': 0.98, 'uniqueness': 0.99}
        return {'status': 'triggered', 'profiling_job_id': profiling_job_id, 'metrics': metrics}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

from fastapi import APIRouter, HTTPException
import yaml
import os

router = APIRouter(prefix='/api/rules', tags=['Rules'])

@router.get('/{dataset_name}')
def get_rules(dataset_name: str):
    try:
        file_path = f'config_rules/{dataset_name}.yml'
        if not os.path.exists(file_path):
            raise HTTPException(status_code=404, detail='Rule file not found')
        with open(file_path, 'r') as f:
            rules_yaml = yaml.safe_load(f)
        return {'rules_yaml': rules_yaml, 'metadata': {'last_updated': '2024-06-10T12:00:00Z', 'owner': 'data_steward'}}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

from fastapi import APIRouter, HTTPException
from utils.alert_manager import send_alert
import uuid

router = APIRouter(prefix='/api/alerts', tags=['Alerts'])

@router.post('/send')
def send_alert_notification(payload: dict):
    try:
        alert_id = str(uuid.uuid4())
        send_alert(payload['severity'], payload['domain'], payload['message'], payload['affected_tables'])
        return {'status': 'sent', 'alert_id': alert_id}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

import requests
import os

SLACK_WEBHOOK = os.getenv('SLACK_WEBHOOK_URL')
PAGERDUTY_API_KEY = os.getenv('PAGERDUTY_API_KEY')


def send_alert(severity: str, domain: str, message: str, affected_tables: list):
    grouped_message = f'[Severity: {severity}] Domain: {domain}\nAffected: {", ".join(affected_tables)}\nMessage: {message}'
    try:
        if SLACK_WEBHOOK:
            requests.post(SLACK_WEBHOOK, json={'text': grouped_message})
        if severity.lower() in ['critical', 'high'] and PAGERDUTY_API_KEY:
            headers = {'Authorization': f'Token token={PAGERDUTY_API_KEY}', 'Content-Type': 'application/json'}
            payload = {'event_action': 'trigger', 'payload': {'summary': grouped_message, 'severity': severity.lower(), 'source': domain}}
            requests.post('https://events.pagerduty.com/v2/enqueue', json=payload, headers=headers)
    except Exception as e:
        print(f'Alert sending failed: {e}')
